[CmdletBinding()]
param([string]$OutputDirectory = "")

$ErrorActionPreference = "Stop"
if ([string]::IsNullOrWhiteSpace($OutputDirectory)) {
    $OutputDirectory = Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) "build-address-test"
}

# Exact, known-good OneROM Selector v1.0.0 PRG.  T0.0.25 deliberately
# reuses its proven IEC M-W/M-E transport; it contains no address-change code.
$selectorBase64 = ''

New-Item -ItemType Directory -Force -Path $OutputDirectory | Out-Null
$outFile = Join-Path $OutputDirectory "1541HUD_UB3_T0.0.25_Selector_Transport_Proof.prg"
[System.IO.File]::WriteAllBytes($outFile, [Convert]::FromBase64String($selectorBase64))
Get-FileHash -Algorithm SHA256 $outFile
Get-Item $outFile | Select-Object Name, Length, LastWriteTime
Write-Host ""
Write-Host "T0.0.25 built: self-contained Selector transport proof."
Write-Host "This is the exact known-good Selector PRG. No address bytes are written."
Write-Host "PASS: its normal ROM-selection menu appears."
